+import { NormalizedErrorStackOptions } from './error-options.js';
+
+export function normalizeStackNewlines(stack: string): string {
+  return stack.replace(/\\r\
?|\
/g, '\
');
+}
+
+function trimLines(lines: string[], options: NormalizedErrorStackOptions) {
+  if (!options.trimLeadingWhitespace) return lines;
+  return lines.map((line, index) => (index === 0 ? line : line.replace(/^\\s+/, '')));
+}
+
+function isInternal(line: string, options: NormalizedErrorStackOptions): boolean {
+  const node = line.includes('node:internal');
+  const superjson = /src\\/(transformer|plainer|index)\\.ts/.test(line);
+  return (
+    (options.stripInternalFrames === 'node' && node) ||
+    (options.stripInternalFrames === 'superjson' && superjson) ||
+    (options.stripInternalFrames === 'node_and_superjson' && (node || superjson))
+  );
+}
+
+function redact(line: string, options: NormalizedErrorStackOptions): string {
+  if (options.redactPaths === 'strip_cwd') {
+    const cwd = process.cwd().replace(/\\\\/g, '/');
+    return line.replace(new RegExp(cwd.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'), 'g'), '');
+  }
+  if (options.redactPaths === 'basename') {
+    return line.replace(/(?:[A-Za-z]:)?(?:\\/|\\\\)(?:[^\\s()\\\\/]+(?:\\/|\\\\))*([^\\s()\\\\/]+)/g, '$1');
+  }
+  return line;
+}
+
+function processLines(stack: string, options: NormalizedErrorStackOptions, frames: boolean) {
+  const normalized = options.normalizeNewlines ? normalizeStackNewlines(stack) : stack;
+  let lines = trimLines(normalized.split(/\\r\
?|\
/), options);
+  if (frames) {
+    lines = [lines[0], ...lines.slice(1).filter(line => !isInternal(line, options))];
+    lines = lines.map(line => redact(line, options));
+  } else {
+    lines = lines.map(line => redact(line, options));
+    lines = [lines[0], ...lines.slice(1).filter(line => !isInternal(line, options))];
+  }
+  return options.maxStackLines === undefined ? lines : lines.slice(0, options.maxStackLines);
+}
+
+export function processStackString(stack: string, options: NormalizedErrorStackOptions): string {
+  return processLines(stack, options, false).join('\
');
+}
+
+export function processStackFrames(stack: string, options: NormalizedErrorStackOptions): { raw: string }[] {
+  return processLines(stack, options, true).map(raw => ({ raw }));
+}
