+function matchesErrorClass(error: Error, superJson: SuperJSON): boolean {
+  const filter = superJson.errorStackOptions?.classFilter;
+  return !filter || filter.includes(error.name);
+}
+
+function errorSource(error: Error, superJson: SuperJSON) {
+  return superJson.errorSourceInfo.get(error) ?? { source: error, depth: 0 };
+}
+
+function causeClone(source: Error, depth: number, superJson: SuperJSON): Error {
+  const existing = superJson.errorCauseClones.get(source);
+  if (existing) return existing;
+  const clone = new Error(source.message);
+  clone.name = source.name;
+  superJson.errorCauseClones.set(source, clone);
+  superJson.errorSourceInfo.set(clone, { source, depth });
+  return clone;
+}
+
+function serializeError(error: Error, superJson: SuperJSON, mode: 'base' | 'string' | 'frames') {
+  const { source, depth } = errorSource(error, superJson);
+  const options = superJson.errorStackOptions;
+  const applies = !!options && matchesErrorClass(source, superJson);
+  const baseError: any = {
+    name: source.name,
+    message:
+      applies && options.sanitizeMessage
+        ? sanitizeMessage(source.message)
+        : source.message,
+  };
+
+  const isAggregate =
+    typeof AggregateError !== 'undefined' && source instanceof AggregateError;
+  if (isAggregate) baseError.errors = (source as AggregateError).errors;
+
+  if (!options) {
+    if ('cause' in source) baseError.cause = (source as any).cause;
+  } else if (applies && options.includeCauses !== 'none') {
+    const maxDepth = options.includeCauses === 'direct' ? 1 : options.maxCauseDepth;
+    const cause = (source as any).cause;
+    if (cause instanceof Error && depth < maxDepth) {
+      baseError.cause = causeClone(cause, depth + 1, superJson);
+    }
+  } else if (!applies && 'cause' in source) {
+    // A filter miss intentionally retains SuperJSON's pre-option behavior.
+    baseError.cause = (source as any).cause;
+  }
+
+  superJson.allowedErrorProps.forEach(prop => {
+    if (options?.mode === 'off' && (prop === 'stack' || prop === 'stackFrames')) {
+      return;
+    }
+    if (mode === 'string' && prop === 'stack') return;
+    if (mode === 'frames' && (prop === 'stack' || prop === 'stackFrames')) return;
+    baseError[prop] = (source as any)[prop];
+  });
+
+  if (mode === 'string' && superJson.allowedErrorProps.includes('stack')) {
+    baseError.stack = processStackString(source.stack ?? '', options!);
+  }
+  if (mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) {
+    baseError.stackFrames = processStackFrames(source.stack ?? '', options!);
+  }
+
+  const processor = applies
+    ? superJson.errorClassRegistry.getProcessor(source.name)
+    : undefined;
+  return processor ? processor(baseError) : baseError;
